// Generate room shells, furnishing regions and reviewed gameplay geometry.
// Walls/windows use the original house tiles. Furnishing areas come from
// village-room-layouts.mjs; the LPC/Kenney renderer selects unmodified frames.
//
// Outputs (all regenerated by this script):
// - apps/client/public/assets/environment/village-interiors/<id>.json  Tiled maps
// - apps/client/src/environment/villageInteriorRegions.json            depth sorting
// - packages/shared/src/villageInteriors.json                          size, spawn,
//   door, outside arrival and reviewed collision (gameplay data, no art)
// `--preview <dir>` also renders each room to <dir>/<id>.png for review.
import fs from "node:fs";
import {
  cleanRoomLayout,
  furnishingFootprint,
} from "./village-room-layouts.mjs";
import { spawnSync } from "node:child_process";
const HOUSE = "apps/client/public/assets/environment/main-house";
const SCALE = 2,
  T = 16,
  U = T * SCALE; // world units per tile
const source = JSON.parse(fs.readFileSync(`${HOUSE}/interior-map.json`));
const firstgid = Object.fromEntries(
  source.tilesets.map((t) => [t.name.split(":")[0], t.firstgid]),
);
const VOID = 13,
  FLOOR = 104,
  FLOOR_VARIANTS = [105, 106, 107, 117];
const BORDER = {
  tl: 134,
  t: 135,
  tr: 136,
  l: 145,
  r: 147,
  bl: 156,
  b: 157,
  br: 158,
};
const FACE = [
  [15, 24, 16],
  [26, 35, 27],
  [37, 46, 38],
];
const BASE = [48, 2, 49],
  DOOR_BASE = [140, 141, 142],
  DOOR_BORDER = [151, 152, 153];
// A window is two wall tiles with glass from the animated sheet over them.
const WINDOW_WALL = [
    [102, 69],
    [113, 80],
  ],
  WINDOW_GLASS = [
    [570, 571],
    [587, 588],
  ];
// Rooms in interior coordinates: `at` is [interior column, row] where row 0
// is the first wall-face row (rows 0-2 are the north wall, the floor starts at
// row 3). `layer`: rug (under everything), wall (hung on the north wall) or
// object (depth-sorted furniture).
const rooms = [
  {
    id: "VILLAGE_COTTAGE",
    name: "Hearthside Cottage",
    width: 12,
    floor: 7,
    door: 6,
    windows: [4, 8],
  },
  {
    id: "VILLAGE_ELDER_HOUSE",
    name: "Elder Bertram's House",
    width: 12,
    floor: 7,
    door: 6,
    windows: [8],
  },
  {
    id: "VILLAGE_APOTHECARY",
    name: "Brynn's Apothecary",
    width: 16,
    floor: 8,
    door: 8,
    windows: [7, 11],
  },
];
// Upper floors have their own furniture layouts and authoritative scenes.
const upstairs = [
  ["VILLAGE_COTTAGE_UPPER", "Hearthside Cottage · Upstairs", "VILLAGE_COTTAGE"],
  [
    "VILLAGE_ELDER_UPPER",
    "Elder Bertram’s House · Upstairs",
    "VILLAGE_ELDER_HOUSE",
  ],
  [
    "VILLAGE_APOTHECARY_UPPER",
    "Brynn’s Apothecary · Upstairs",
    "VILLAGE_APOTHECARY",
  ],
  [
    "WILLOWBANK_HOME_UPPER",
    "Willowbank Riverside Home · Upstairs",
    "WILLOWBANK_HOME",
  ],
  ["STONEBRIDGE_INN_UPPER", "Stonebridge Inn · Guest Rooms", "STONEBRIDGE_INN"],
];
rooms.push(
  {
    ...rooms[0],
    id: "WILLOWBANK_HOME",
    name: "Willowbank Riverside Home",
    outsideScene: "WILLOWBANK_VILLAGE",
    windows: [4, 8],
  },
  {
    ...rooms[2],
    id: "STONEBRIDGE_INN",
    name: "Stonebridge Inn · Common Room",
    outsideScene: "STONEBRIDGE_TOWN",
    windows: [4, 10],
  },
);
for (const [id, name, parent] of upstairs) {
  const base = rooms.find((r) => r.id === parent);
  rooms.push({
    ...base,
    id,
    name,
    outsideScene: parent,
    windows: [4, 8],
  });
}
// Village doors (world units on EMBERBROOK_VILLAGE), just outside each
// house's reviewed collision footprint, and where heroes arrive back outside.
const doors = {
  VILLAGE_COTTAGE: { door: { x: 190, y: 270 }, outside: { x: 190, y: 284 } },
  VILLAGE_ELDER_HOUSE: {
    door: { x: 186, y: 510 },
    outside: { x: 186, y: 524 },
  },
  VILLAGE_APOTHECARY: { door: { x: 797, y: 312 }, outside: { x: 797, y: 326 } },
};
doors.WILLOWBANK_HOME = {
  door: { x: 312, y: 376 },
  outside: { x: 312, y: 398 },
};
doors.STONEBRIDGE_INN = {
  door: { x: 440, y: 484 },
  outside: { x: 440, y: 506 },
};
for (const [id, , parent] of upstairs)
  doors[id] = {
    door: { x: 0, y: 0 },
    outside: {
      x:
        parent === "VILLAGE_APOTHECARY" || parent === "STONEBRIDGE_INN"
          ? 548
          : 440,
      y: 300,
    },
  };
const MARGIN = 2;
const out = { maps: {}, regions: {}, shared: {} };
for (const room of rooms) {
  const iw = room.width,
    R0 = MARGIN,
    C0 = MARGIN + 1, // first interior column
    RB = R0 + 4 + room.floor, // base row (walkable trim with the doorway)
    W = iw + 2 + MARGIN * 2,
    H = RB + 2 + MARGIN;
  const layer = (name) => ({ name, data: new Array(W * H).fill(0) });
  const floor = layer("Floor"),
    walls = layer("Walls"),
    windows = layer("Windows");
  const set = (l, c, r, gid) => (l.data[r * W + c] = gid);
  const layers = [floor, walls, windows];
  const regions = [];
  // Room shell.
  for (let r = 0; r < H; r++)
    for (let c = 0; c < W; c++) set(walls, c, r, VOID);
  for (let r = R0 + 1; r <= RB; r++)
    for (let c = C0; c < C0 + iw; c++) {
      set(walls, c, r, 0);
      // Deterministic, sparse plank variety like the main house floor.
      const h = (c * 7919 + r * 104729 + room.id.length * 31) % 23;
      set(floor, c, r, h < 4 ? FLOOR_VARIANTS[h] : FLOOR);
    }
  set(walls, C0 - 1, R0, BORDER.tl);
  set(walls, C0 + iw, R0, BORDER.tr);
  for (let c = C0; c < C0 + iw; c++) set(walls, c, R0, BORDER.t);
  for (let r = R0 + 1; r <= RB; r++) {
    set(walls, C0 - 1, r, BORDER.l);
    set(walls, C0 + iw, r, BORDER.r);
  }
  set(walls, C0 - 1, RB + 1, BORDER.bl);
  set(walls, C0 + iw, RB + 1, BORDER.br);
  for (let c = C0; c < C0 + iw; c++) set(walls, c, RB + 1, BORDER.b);
  FACE.forEach((row, k) => {
    for (let c = C0; c < C0 + iw; c++)
      set(
        walls,
        c,
        R0 + 1 + k,
        c === C0 ? row[0] : c === C0 + iw - 1 ? row[2] : row[1],
      );
  });
  for (let c = C0; c < C0 + iw; c++)
    set(
      walls,
      c,
      RB,
      c === C0 ? BASE[0] : c === C0 + iw - 1 ? BASE[2] : BASE[1],
    );
  const dc = C0 + room.door;
  [-1, 0, 1].forEach((d, k) => {
    set(walls, dc + d, RB, DOOR_BASE[k]);
    set(walls, dc + d, RB + 1, DOOR_BORDER[k]);
  });
  for (const at of room.windows)
    for (let k = 0; k < 2; k++)
      for (let d = 0; d < 2; d++) {
        set(walls, C0 + at + d, R0 + 2 + k, WINDOW_WALL[k][d]);
        set(
          windows,
          C0 + at + d,
          R0 + 2 + k,
          firstgid.Doors_windows_animation - 555 + WINDOW_GLASS[k][d],
        );
      }
  // Clean furnishing areas are reviewed independently from sprite frames.
  const solids = [];
  cleanRoomLayout(room.id).forEach((o, n) => {
    const name = `${o.kind}-${n}`;
    const l = layer(`${o.kind === "rug" ? "Rug" : "Furniture"}-${name}`);
    layers.push(l);
    regions.push({
      id: name,
      category: o.kind === "rug" ? "path" : "object",
      layer: l.name,
      bounds: [o.x / U, o.y / U, (o.x + o.w) / U, (o.y + o.h) / U],
      groundY: o.kind === "rug" ? undefined : o.y + o.h,
      layoutBounds: { x: o.x, y: o.y, w: o.w, h: o.h },
    });
    const footprint = furnishingFootprint(o);
    if (footprint) solids.push(footprint);
  });
  // Room boundary: everything outside the floor, the north wall down to its
  // walkable bottom face row, and the south wall (doors are left with E).
  const left = C0 * U,
    right = (C0 + iw) * U,
    top = (R0 + 3) * U,
    bottom = (RB + 1) * U;
  solids.unshift(
    { x: 0, y: 0, w: W * U, h: top },
    { x: 0, y: 0, w: left, h: H * U },
    { x: right, y: 0, w: W * U - right, h: H * U },
    { x: 0, y: bottom, w: W * U, h: H * U - bottom },
  );
  out.maps[room.id] = {
    compressionlevel: -1,
    width: W,
    height: H,
    tilewidth: T,
    tileheight: T,
    infinite: false,
    orientation: "orthogonal",
    renderorder: "right-down",
    type: "map",
    version: "1.10",
    tiledversion: "1.10.2",
    nextlayerid: layers.length + 1,
    nextobjectid: 1,
    layers: layers.map((l, i) => ({
      id: i + 1,
      name: l.name,
      type: "tilelayer",
      x: 0,
      y: 0,
      width: W,
      height: H,
      opacity: 1,
      visible: true,
      data: l.data,
    })),
    tilesets: source.tilesets,
  };
  // Walls and windows sort with the north wall's walkable bottom face row.
  out.regions[room.id] = { wallGroundY: (R0 + 3) * U, regions };
  out.shared[room.id] = {
    name: room.name,
    ...(room.outsideScene ? { outsideScene: room.outsideScene } : {}),
    width: W * U,
    height: H * U,
    cameraBounds: {
      x: (C0 - 1) * U,
      y: R0 * U,
      w: (iw + 2) * U,
      h: (RB + 2 - R0) * U,
    },
    spawn: { x: (dc + 0.5) * U, y: RB * U - 4 },
    leave: { x: (dc + 0.5) * U, y: (RB + 0.5) * U },
    doorInteractionBounds: {
      x: (dc - 1) * U,
      y: (RB - 1) * U,
      w: 3 * U,
      h: 2 * U,
    },
    ...doors[room.id],
    solids,
  };
}
const mapsDir = "apps/client/public/assets/environment/village-interiors";
fs.mkdirSync(mapsDir, { recursive: true });
for (const [id, map] of Object.entries(out.maps))
  fs.writeFileSync(
    `${mapsDir}/${id.toLowerCase()}.json`,
    JSON.stringify(map) + "\n",
  );
fs.writeFileSync(
  "apps/client/src/environment/villageInteriorRegions.json",
  JSON.stringify(out.regions, null, 2) + "\n",
);
fs.writeFileSync(
  "packages/shared/src/villageInteriors.json",
  JSON.stringify(out.shared, null, 2) + "\n",
);
console.log(
  Object.keys(out.maps)
    .map((id) => `${id}: ${out.maps[id].width}x${out.maps[id].height} tiles`)
    .join("\n"),
);

// Render the same LPC/Kenney frames the browser uses, not blank stamp layers.
const previewAt = process.argv.indexOf("--preview");
if (previewAt > 0) {
  const run = spawnSync(
    process.execPath,
    [
      "--import",
      "tsx",
      "scripts/render-town-previews.ts",
      process.argv[previewAt + 1],
    ],
    { stdio: "inherit" },
  );
  if (run.status) process.exit(run.status);
}
